  ['width','profile','rim','text'].forEach(k=>qsa(`.li-stock-${k}`).forEach(el=>el.oninput=()=>{const n=Number(el.dataset.i);lineItems[n][`stock${k[0].toUpperCase()+k.slice(1)}`]=el.value;const sel=qs(`.li-stock[data-i="${n}"]`);if(sel){sel.innerHTML=orderStockOptions(available,lineItems[n]);lineItems[n].stockId=''}}));
