function openStockForm(item=null){const editing=!!item,type=item?.type||'tire';modal(`<h2>${editing?'Editar':'Cadastrar'} estoque</h2><form id="stockEditForm" class="form-grid"><label>Tipo<select id="stockType" name="type"><option value="tire" ${type==='tire'?'selected':''}>Pneu</option><option value="material" ${type==='material'?'selected':''}>Material / produto</option></select></label><div></div><div id="stockDynamic" class="full"></div><label>Quantidade<input name="qty" type="number" min="0" step="1" value="${item?.qty??0}" required></label><label>Estoque mínimo<input name="min" type="number" min="0" step="1" value="${item?.min??0}" required></label><label>Custo de compra<input name="costPrice" type="number" min="0" step="0.01" value="${item?.costPrice??0}"></label><label>Preço de venda<input name="salePrice" type="number" min="0" step="0.01" value="${item?.salePrice??0}"></label><label>Localização<input name="location" value="${esc(item?.location||'')}"></label><label>Fornecedor<input name="supplier" value="${esc(item?.supplier||'')}"></label><label class="full">Observações<textarea name="notes">${esc(item?.notes||'')}</textarea></label><div class="full"><button class="btn btn-primary">Salvar</button></div></form>`);const renderDynamic=()=>{const t=qs('#stockType').value;if(t==='material'){qs('#stockDynamic').innerHTML=`<div class="form-grid"><label>Nome do material<input name="item" value="${esc(item?.item||'')}" required></label><label>Categoria<input name="category" value="${esc(item?.category||'Material')}" placeholder="Ex.: válvula, remendo, cola"></label></div>`}else{const special=['Quadriciclo','Carrinho de mão','Agrícola','Implemento/reboque'].includes(item?.category);qs('#stockDynamic').innerHTML=`<div class="form-grid"><label>Categoria<select id="tireCategory" name="category"><option>Automóvel</option><option>SUV/Picape</option><option>Moto</option><option>Quadriciclo</option><option>Carrinho de mão</option><option>Implemento/reboque</option><option>Agrícola</option><option>Outro</option></select></label><label>Condição<select name="condition"><option>Novo</option><option>Usado</option><option>Recauchutado/Remold</option><option>Meia-vida</option></select></label><label>Marca<input name="brand" value="${esc(item?.brand||'')}"></label><label>Modelo<input name="model" value="${esc(item?.model||'')}"></label><div id="measureFields" class="full"></div><label>Índice carga/velocidade<input name="loadSpeed" value="${esc(item?.loadSpeed||'')}"></label><label>Tipo<select name="tubeType"><option>Sem câmara</option><option>Com câmara</option></select></label><label>DOT / ano<input name="dot" value="${esc(item?.dot||'')}"></label><label>Estado do sulco (usado)<input name="tread" value="${esc(item?.tread||'')}" placeholder="Ex.: 6 mm ou 70%"></label><label>Possui remendo?<select name="hasPatch"><option value="false">Não</option><option value="true">Sim</option></select></label><label>Avaria/bolha<input name="damage" value="${esc(item?.damage||'')}"></label></div>`;const cat=qs('#tireCategory');cat.value=item?.category||'Automóvel';const mf=()=>renderMeasureFields(item);cat.onchange=mf;mf();const cond=qs('[name=condition]');cond.value=item?.condition||'Novo';const tube=qs('[name=tubeType]');tube.value=item?.tubeType||'Sem câmara';qs('[name=hasPatch]').value=String(item?.hasPatch||false)}};qs('#stockType').onchange=renderDynamic;renderDynamic();qs('#stockEditForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),data={type:f.get('type'),qty:Number(f.get('qty')),min:Number(f.get('min')),costPrice:Number(f.get('costPrice')||0),salePrice:Number(f.get('salePrice')||0),location:f.get('location'),supplier:f.get('supplier'),notes:f.get('notes'),updatedAt:serverTimestamp()};if(data.type==='material'){Object.assign(data,{item:f.get('item'),category:f.get('category')||'Material'})}else{Object.assign(data,{category:f.get('category'),condition:f.get('condition'),brand:f.get('brand'),model:f.get('model'),measure:buildMeasure(f),loadSpeed:f.get('loadSpeed'),tubeType:f.get('tubeType'),dot:f.get('dot'),tread:f.get('tread'),hasPatch:f.get('hasPatch')==='true',damage:f.get('damage')})}if(editing)await updateDoc(doc(db,'tenants',tenant,'stock',item.id),data);else{data.createdAt=serverTimestamp();const ref=await addDoc(collection(db,'tenants',tenant,'stock'),data);if(data.qty>0)await addDoc(collection(db,'tenants',tenant,'stockMovements'),{stockId:ref.id,itemName:data.type==='tire'?`${data.brand||''} ${data.measure}`.trim():data.item,type:'entrada',qty:data.qty,reason:'Estoque inicial',employee:session.name,createdBy:session.uid,createdAt:serverTimestamp()})}toast('Estoque salvo.');closeModal()}}
function renderMeasureFields(item){const category=qs('#tireCategory').value,special=['Quadriciclo','Carrinho de mão','Agrícola','Implemento/reboque'].includes(category),m=item?.measure||'';if(special){const parts=m.replace(/^AT\s*/,'').split(/[x-]/);qs('#measureFields').innerHTML=`<div class="form-grid"><label>Diâmetro externo<select id="spDiameter" name="spDiameter">${selectOptions(SPECIAL_DIAMETERS,parts[0]||'')}</select></label><label>Largura<select id="spWidth" name="spWidth">${selectOptions(SPECIAL_WIDTHS,parts[1]||'')}</select></label><label>Aro<select id="spRim" name="spRim">${selectOptions(RIMS,parts[2]||'')}</select></label><label>Medida personalizada<input name="customMeasure" value="${esc(parts.length<3?m:'')}" placeholder="Ex.: 4.10/3.50-4"></label><div class="full measure-preview" id="measurePreview"></div></div>`}else{const p=m.match(/(\d+)\/(\d+)\s*R?([\d.]+)/i)||[];qs('#measureFields').innerHTML=`<div class="form-grid"><label>Largura<select id="width" name="width">${selectOptions(WIDTHS,p[1]||'')}</select></label><label>Altura/perfil<select id="profile" name="profile">${selectOptions(PROFILES,p[2]||'')}</select></label><label>Aro<select id="rim" name="rim">${selectOptions(RIMS,p[3]||'')}</select></label><label>Medida personalizada<input name="customMeasure" value="${esc(!p.length?m:'')}" placeholder="Ex.: 31x10.50 R15"></label><div class="full measure-preview" id="measurePreview"></div></div>`}const upd=()=>{const f=new FormData(qs('#stockEditForm'));qs('#measurePreview').textContent=buildMeasure(f)||'Selecione a medida'};qsa('#measureFields select,#measureFields input').forEach(x=>x.oninput=upd);upd()}
