function openMovement(item){modal(`<h2>Movimentar estoque</h2><p><strong>${esc(stockName(item))}</strong> — atual: ${item.qty}</p><form id="movementForm" class="form-stack"><label>Tipo<select name="type"><option value="entrada">Entrada</option><option value="saida">Saída</option><option value="ajuste">Ajuste para quantidade exata</option></select></label><label>Quantidade<input name="qty" type="number" min="0" step="1" required></label><label>Motivo<input name="reason" required placeholder="Compra, venda, perda, conferência..."></label><button class="btn btn-primary">Confirmar movimentação</button></form>`);qs('#movementForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),type=f.get('type'),qty=Number(f.get('qty'));let next=Number(item.qty);if(type==='entrada')next+=qty;if(type==='saida')next-=qty;if(type==='ajuste')next=qty;if(next<0)return toast('A quantidade não pode ficar negativa.');await updateDoc(doc(db,'tenants',tenant,'stock',item.id),{qty:next,updatedAt:serverTimestamp()});await addDoc(collection(db,'tenants',tenant,'stockMovements'),{stockId:item.id,itemName:stockName(item),type,qty,previousQty:Number(item.qty),newQty:next,reason:f.get('reason'),employee:session.name,createdBy:session.uid,createdAt:serverTimestamp()});toast('Movimentação registrada.');closeModal()}}
function renderServices(){if(!can('servicesManage'))return;qs('#servicesPage').innerHTML=`<div class="toolbar"><h1 class="page-title">Serviços e preços</h1><div class="actions"><button id="seedServices" class="btn btn-secondary">Cadastrar lista inicial</button><button id="addService" class="btn btn-primary">Novo serviço</button></div></div><div class="card table-wrap"><table><thead><tr><th>Serviço</th><th>Categoria</th><th>Veículos</th><th>Preço normal</th><th>Status</th><th>Ações</th></tr></thead><tbody>${services.sort((a,b)=>a.name.localeCompare(b.name)).map(s=>`<tr><td>${esc(s.name)}</td><td>${esc(s.category||'Geral')}</td><td>${esc((s.vehicleTypes||['Todos']).join(', '))}</td><td>${money(s.price)}</td><td>${s.active!==false?'Ativo':'Inativo'}</td><td><div class="actions"><button class="btn btn-small btn-secondary editService" data-id="${s.id}">Editar</button><button class="btn btn-small ${s.active!==false?'btn-danger':'btn-success'} toggleService" data-id="${s.id}">${s.active!==false?'Desativar':'Ativar'}</button></div></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum serviço cadastrado.</td></tr>'}</tbody></table></div>`;qs('#addService').onclick=()=>openService();qs('#seedServices').onclick=seedDefaultServices;qsa('.editService').forEach(b=>b.onclick=()=>openService(services.find(s=>s.id===b.dataset.id)));qsa('.toggleService').forEach(b=>b.onclick=()=>{const s=services.find(x=>x.id===b.dataset.id);updateDoc(doc(db,'tenants',tenant,'services',s.id),{active:s.active===false,updatedAt:serverTimestamp()})})}
